async function retryPayment(paymentId) {
  let attempts = 0;
  const maxAttempts = 5;
  while (attempts < maxAttempts) {
    try {
      await processPayment(paymentId);
      break;
    } catch (error) {
      attempts++;
      await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempts) * 1000));
    }
  }
}

